package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class UsersSketchVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property users sketch of observed issue ")
  void test_users_sketch_v_o_builder() {
    Assertions.assertFalse(UsersSketchVO.nullValue().getUsersSketch().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(UsersSketchVO.tryFrom(null).getUsersSketch().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", UsersSketchVO.from("one").getUsersSketch().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> UsersSketchVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", UsersSketchVO.from("one").toString());
  }
}
